roup"><label class="form-label">Semestre</label><input type="number" min="1" max="20" name="semestre" value="<?=e($registro['semestre']??'')?>"></div><div class="form-group"><label class="form-label">Estado</label><select name="estado"><option value="activo" <?=($registro['estado']??'activo')==='activo'?'selected':''?>>Activo</option><option value="inactivo" <?=($registro['estado']??'')==='inactivo'?'selected':''?>>Inactivo</option></select></div></div><div class="form-group"><label class="form-label">Descripción</label><textarea name="descripcion" minlength="20" placeholder="Describe brevemente los contenidos y objetivos del curso."><?=e($registro['descripcion']??'')?></textarea><div class="form-help">Si completas este campo, escribe una descripción real de al menos cuatro palabras.</div></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/cursos.php">Cancelar</a></div></form></div></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
